    if eseen.keys()!=targets:
        raise AssertionError("Explorer Known Folder rows missing: "+repr(sorted(targets-set(eseen))))
    print("EXPLORER_KNOWN_FOLDER_COUNT",len(eseen),flush=True)
    for key in sorted(eseen):
        print("EXPLORER_KNOWN_FOLDER_ROW",key,repr(eseen[key]),flush=True)
    print("EXPLORER_SCREENSHOT_BEGIN",flush=True);print(shot(exp),flush=True);print("EXPLORER_SCREENSHOT_END",flush=True)
finally:
    if exp:
        try:exp.close()
        except Exception:pass

